/* Visual QA mobile: proportional header, dense listings, tidy footer. */
@media(max-width:767px){
.tcStitchShell .tcMobilePlace{display:none!important}
.tcStitchShell .tcTopbarInner{padding-inline:16px!important;gap:10px!important}
.tcStitchShell .neoBrand{flex:1 1 auto!important;min-width:0!important}
.tcStitchShell .tcStitchBrandArt{width:27px!important}
.tcStitchShell .tcStitchBrand img{width:27px!important;height:28px!important}
.tcStitchShell .tcStitchMobileWordmark b{font-size:17px!important;line-height:20px!important;letter-spacing:-.025em!important}
.tcStitchShell .tcStitchMobileWordmark small{font-size:10px!important;line-height:13px!important}
.tcStitchShell .tcSiteMenu{flex:0 0 auto!important}
.tcStitchShell .tcSiteMenu>summary{width:40px!important;min-width:40px!important;height:40px!important;min-height:40px!important;padding:8px!important}
.tcStitchShell .neoJobCard{border-radius:12px!important}
.tcStitchShell .neoJobBody{grid-template-columns:minmax(0,1fr) auto!important;grid-template-rows:auto auto auto!important;gap:3px!important;padding:11px!important}
.tcStitchShell .neoJobCard h3{font-size:14px!important;line-height:19px!important;font-weight:650!important;display:-webkit-box!important;-webkit-line-clamp:2!important;-webkit-box-orient:vertical!important;white-space:normal!important;overflow:hidden!important;text-overflow:ellipsis!important;overflow-wrap:anywhere!important}
.tcStitchShell .neoJobCompany{font-size:12px!important;line-height:16px!important}
.tcStitchShell .neoJobTop{max-width:85px!important;gap:3px!important}
.tcStitchShell .neoJobPlace,.tcStitchShell .neoJobState{font-size:10px!important;line-height:13px!important}
.tcStitchShell .tcOfferActionRow{min-height:36px!important;margin-top:5px!important}
.tcStitchShell .neoJobFacts small,.tcStitchShell .neoJobFacts b{font-size:10px!important;line-height:14px!important}
.tcStitchShell .neoJobFoot button{min-height:34px!important;padding:7px 9px!important;font-size:12px!important;line-height:17px!important}
.tcStitchShell .tcStitchFooterDetails{margin:0 12px!important}
.tcStitchShell .tcStitchFooterDetails>summary{font-size:12px!important;line-height:17px!important;max-width:100%!important;padding:9px 0!important}
.tcStitchShell .tcSecondary{width:100%!important;max-width:100%!important}
.tcStitchShell .tcSecondary>summary{font-size:12px!important;line-height:18px!important;padding:10px 4px!important}
.tcStitchShell .neoFooter{display:grid!important;grid-template-columns:minmax(0,1fr)!important;gap:6px!important;padding:14px 12px!important;margin-top:8px!important;min-width:0!important;border-radius:12px!important}
.tcStitchShell .neoFooter .tcStitchBrand{width:auto!important}
.tcStitchShell .neoFooter .tcStitchBrand img{width:22px!important;height:25px!important}
.tcStitchShell .neoFooter .tcStitchMobileWordmark b{font-size:14px!important}
.tcStitchShell .neoFooter .tcStitchMobileWordmark small{font-size:10px!important}
.tcStitchShell .tcFooterTagline{font-size:12px!important;line-height:18px!important;margin:0!important}
.tcStitchShell .tcFooterEmail{display:block!important;min-width:0!important;width:100%!important;overflow-wrap:anywhere!important;word-break:break-word!important;font-size:11px!important;line-height:16px!important}
.tcStitchShell .tcFooterLegal{display:flex!important;flex-wrap:wrap!important;align-items:center!important;gap:14px!important}
.tcStitchShell .tcFooterLegal button{font-size:12px!important;min-height:32px!important}
.tcStitchShell .neoDrawer{width:100vw!important;max-width:100vw!important;max-height:100dvh!important;overflow:auto!important}
.tcStitchShell .neoDrawerHeader h2{font-size:21px!important;line-height:1.25!important;overflow-wrap:anywhere!important}
.tcStitchShell .neoDrawerHeader{padding:22px 16px 12px!important}
.tcStitchShell .neoDrawerClose{width:40px!important;height:40px!important}
.tcStitchShell .neoDrawer p,.tcStitchShell .neoDrawer span{overflow-wrap:anywhere}
}

.opsShell {
  min-height: 100vh;
  background: #f4f6f3;
  color: #163d32;
  padding-bottom: 24px;
}
.opsShell *, .opsShell *::before, .opsShell *::after { box-sizing: border-box; }
.opsShell .opsHeader {
  min-height: 80px; height: auto; gap: 16px; padding: 16px max(24px, calc((100% - 1092px) / 2));
  background: #fff; border-bottom: 1px solid #dce5de;
}
.opsShell .opsHeader .brand { min-width: 0; }
.opsShell .opsHeader .brand b { font-size: 18px; }
.opsShell .opsHeader .brand span { font-size: 10px; letter-spacing: .08em; }
.opsShell .opsHeader > button {
  min-height: 44px; padding: 10px 16px; font-size: 12px; border-radius: 12px; flex-shrink: 0;
}
.opsShell .opsHero { max-width: 1140px; padding: 32px 24px 24px; margin: 0 auto; }
.opsShell .overline { font-size: 11px; font-weight: 750; line-height: 1.5; letter-spacing: .09em; color: #536e61; }
.opsShell .opsHero h1 { font-size: clamp(28px, 4vw, 40px); line-height: 1.15; letter-spacing: -.035em; margin: 10px 0; }
.opsShell .opsHero p { font-size: 15px; line-height: 1.6; color: #5c7167; margin: 0; }
.opsShell .tcAdminAccess {
  max-width: 1092px; margin: 0 auto 20px; padding: 24px;
  background: #fff; border: 1px solid #dce5de; border-radius: 20px; box-shadow: 0 4px 18px #143c2d05;
}
.tcAdminTitle { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; justify-content: space-between; }
.opsShell .tcAdminAccess h2 { font-size: 19px; line-height: 1.3; letter-spacing: -.02em; margin: 0; }
.tcAdminBadge { display: inline-flex; padding: 5px 10px; border-radius: 99px; background: #f0f3ef; color: #5e6e63; font-size: 12px; font-weight: 650; }
.tcAdminBadge[data-allowed=true] { background: #e4f3e8; color: #23663d; }
.opsShell .tcAdminAccess p { font-size: 14px; line-height: 1.6; color: #5c7167; margin: 12px 0 0; max-width: 720px; }
.opsShell .tcAdminActions { margin: 20px 0 0; gap: 10px; }
.opsShell .tcAdminActions button { border-radius: 12px; font-size: 14px; padding: 12px 18px; min-height: 46px; }
.opsShell .opsReadiness {
  max-width: 1092px; margin: 0 auto 24px; padding: 18px 20px; display: flex; gap: 14px;
  align-items: flex-start; background: #fff7e9; border: 1px solid #ead8b5; border-radius: 16px;
}
.opsReadiness > svg { width: 22px; height: 22px; flex-shrink: 0; color: #926219; }
.opsReadiness > div { flex: 1; min-width: 0; }
.opsReadiness b { font-size: 14px; }
.opsReadiness p { font-size: 13px; line-height: 1.6; margin: 6px 0 0; color: #78643e; }
.opsReadiness > span { font-size: 11px; padding: 4px 8px; border-radius: 6px; background: #f5e8ce; color: #765018; }
.opsShell .opsGrid { max-width: 1140px; padding: 0 24px; gap: 14px; }
.opsShell .opsGrid article { min-width: 0; border: 1px solid #dce5de; border-radius: 18px; padding: 20px; box-shadow: 0 3px 12px #143c2d03; }
.opsShell .opsGrid article span { font-size: 11px; line-height: 1.5; color: #5c7167; letter-spacing: .055em; }
.opsShell .opsGrid article b { font-size: 38px; line-height: 1.15; margin: 12px 0 8px; letter-spacing: -.04em; }
.opsShell .opsGrid article small { font-size: 12px; line-height: 1.6; color: #65766d; }
.opsInventoryNote { max-width: 1140px; margin: 12px auto 0; padding: 0 24px; font-size: 12px; line-height: 1.6; color: #65766d; }
.opsShell .opsColumns { max-width: 1140px; padding: 0 24px; gap: 16px; margin-top: 24px; }
.opsShell .opsColumns .opsCard { padding: 24px; border: 1px solid #dce5de; border-radius: 18px; }
.opsShell .opsLine { padding: 16px 0; gap: 16px; align-items: flex-start; border-color: #e9eee9; }
.opsShell .opsLine > div { min-width: 0; gap: 10px; align-items: flex-start; }
.opsShell .opsLine svg { height: 18px; width: 18px; flex-shrink: 0; }
.opsShell .opsLine span { font-size: 14px; line-height: 1.5; }
.opsShell .opsLine b { font-size: 14px; line-height: 1.5; text-align: right; max-width: 45%; }
.opsShell .opsPrivacy { max-width: 1092px; padding: 18px 20px; margin: 20px auto 0; border: 1px solid #dce5de; gap: 12px; }
.opsShell .opsPrivacy > svg { width: 22px; height: 22px; flex-shrink: 0; }
.opsShell .opsPrivacy b { font-size: 13px; }
.opsShell .opsPrivacy span { font-size: 12px; line-height: 1.6; }
.opsShell .opsUpdated { font-size: 12px; line-height: 1.6; padding: 16px 24px 28px; }
.opsShell .opsError, .opsShell .opsLoading { font-size: 14px; }
.opsShell pre { max-width: 100%; overflow: auto; font-size: 12px; }
@media (max-width: 700px) {
  .opsShell .opsHeader { padding: 14px 16px; min-height: 72px; }
  .opsShell .opsHeader .brand b { font-size: 16px; }
  .opsShell .opsHeader .brand span { font-size: 8px; }
  .opsShell .opsHeader > button { max-width: 124px; padding: 9px 12px; font-size: 11px; }
  .opsShell .opsHero { padding: 26px 16px 22px; }
  .opsShell .tcAdminAccess { margin: 0 16px 16px; padding: 20px; border-radius: 18px; }
  .opsShell .opsReadiness { margin: 0 16px 20px; padding: 16px; gap: 10px; }
  .opsReadiness > span { display: none; }
  .opsShell .opsGrid { padding: 0 16px; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
  .opsShell .opsGrid article { padding: 16px; }
  .opsShell .opsGrid article b { font-size: 34px; }
  .opsShell .opsGrid article span { font-size: 10px; letter-spacing: .03em; }
  .opsShell .opsColumns { padding: 0 16px; grid-template-columns: minmax(0, 1fr); gap: 16px; margin-top: 20px; }
  .opsShell .opsColumns .opsCard { padding: 20px; }
  .opsInventoryNote { padding: 0 16px; }
  .opsShell .opsPrivacy { margin: 16px 16px 0; padding: 16px; }
  .opsShell .opsUpdated { padding: 16px 16px 28px; }
}
@media (prefers-reduced-motion: no-preference) {
  .tcAdminActions button { transition: background-color .15s, border-color .15s; }
}

import {useState,type FormEvent} from 'react';
import {api} from '@appdeploy/client';
import {COMMERCIAL_PLACES} from '../shared/commercial-policy';
export function OwnedPublicationEditor({item,ownerToken,onSaved}:{item:{id:string;title:string;note:string;workLocation:string};ownerToken:string;onSaved:()=>void}){
  const [title,setTitle]=useState(item.title);const [detail,setDetail]=useState(item.note);
  const [place,setPlace]=useState(item.workLocation);const [contact,setContact]=useState('');
  const [renew,setRenew]=useState(false);const [consent,setConsent]=useState(false);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');
  async function save(e:FormEvent){e.preventDefault();setBusy(true);try{await api.post('/api/listings/'+item.id+'/manage',{ownerToken,title,detail,workLocation:place,contact,renew,consent});onSaved();}catch{setMessage('No se guardó. Revisa los datos y utiliza el dispositivo desde el que publicaste.');}finally{setBusy(false);}}
  return <details className='tcOwnedEditor'><summary>Editar o renovar mi publicación gratuita</summary><form onSubmit={save}>
    <label>Oficio, servicio o necesidad<input required maxLength={140} value={title} onChange={e=>setTitle(e.target.value)}/></label>
    <label>Descripción<textarea maxLength={1200} value={detail} onChange={e=>setDetail(e.target.value)}/></label>
    <label>Comuna<select value={place} onChange={e=>setPlace(e.target.value)}>{COMMERCIAL_PLACES.map(p=><option key={p}>{p}</option>)}</select></label>
    <label>Nuevo contacto, opcional; vacío conserva el actual<input maxLength={100} value={contact} onChange={e=>setContact(e.target.value)}/></label>
    <label><input type='checkbox' checked={renew} onChange={e=>setRenew(e.target.checked)}/>Renovar vigencia gratuitamente desde hoy</label>
    <label><input type='checkbox' required checked={consent} onChange={e=>setConsent(e.target.checked)}/>Autorizo a publicar estos cambios y facilitar mi contacto.</label>
    <p role='status'>{message}</p><button disabled={busy} type='submit'>{busy?'Guardando…':'Guardar cambios'}</button>
  </form></details>;
}

/* Presentation only: allocation, editorial evidence and commercial terms are unchanged. */
.tcPremiumCommercial .tcCommercialVisual {
  position:relative;
  min-width:0;
  overflow:hidden;
  background:#dce8d6;
  align-self:stretch
}
.tcLocalAdvertising .tcPremiumCommercial .tcCommercialVisual .tcAdImage {
  position:absolute;
  inset:0;
  display:block;
  width:100%;
  height:100%;
  object-fit:contain;
  object-position:center;
  border-radius:0
}
.tcCreativeFallback {
  position:absolute;
  inset:0;
  display:grid;
  place-items:center;
  padding:14px;
  text-align:center;
  color:#31533b;
  font-size:14px;
  font-weight:700;
  background:repeating-linear-gradient(140deg,#edf3e5 0 28px,#e1ebd8 28px 29px)
}
.tcCommercialVisual:has(>.tcAdImage)>.tcCreativeFallback {
  display:none
}
.tcCreativeExample {
  position:absolute;
  bottom:8px;
  left:8px;
  right:8px;
  justify-self:start;
  border-radius:5px;
  padding:4px 6px;
  font-size:10px;
  line-height:1.2;
  color:#173c2b;
  background:#fafdf1ed
}
.tcLocalAdvertising .tcAdContent.tcPremiumCommercial {
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  gap:14px;
  align-items:center;
  margin-top:10px
}
.tcLocalAdvertising .tcAdContent.tcPremiumCommercial[data-has-image=true] {
  grid-template-columns:38% minmax(0,1fr) auto
}
.tcLocalAdvertising .tcPremiumCommercial .tcCommercialVisual {
  min-height:140px;
  border-radius:10px
}
.tcLocalAdvertising .tcPremiumCommercial .tcCommercialVisual:has(>.tcAdImage) {
  min-height:140px
}
.tcLocalAdvertising .tcPremiumCommercial p {
  font-size:14px;
  line-height:1.4;
  margin:6px 0
}
.tcLocalAdvertising .tcPremiumCommercial .tcAdBusiness strong {
  font-size:18px;
  line-height:1.3
}
@media(max-width:800px) {
  .tcLocalAdvertising .tcAdContent.tcPremiumCommercial {
    grid-template-columns:minmax(0,1fr);
    gap:8px
  }
  .tcLocalAdvertising .tcAdContent.tcPremiumCommercial[data-has-image=true] {
    grid-template-columns:minmax(92px,30%) minmax(0,1fr);
    align-items:center
  }
  .tcLocalAdvertising .tcPremiumCommercial .tcCommercialVisual {
    grid-row:1;
    min-height:116px;
    height:100%
  }
  .tcLocalAdvertising .tcPremiumCommercial>a {
    grid-column:1/-1;
    min-height:44px;
    justify-self:end;
    font-size:13px;
    padding:8px 10px;
    max-width:100%;
    box-sizing:border-box
  }
  .tcLocalAdvertising .tcPremiumCommercial:not([data-has-image=true])>a {
    grid-column:1/-1
  }
  .tcLocalAdvertising .tcPremiumCommercial .tcAdBusiness strong {
    font-size:15px
  }
  .tcLocalAdvertising .tcPremiumCommercial p {
    font-size:12px
  }
}
/* Single owner: public home/search/activity. Earlier rules were removed, not overridden. */
@media(max-width:800px) {
  /* Compact fintech-like density: no loss of the four primary actions. */
}
/* iOS keeps 16px text inputs to avoid focus zoom; viewport zoom stays available. */
@supports(-webkit-touch-callout:none) {
}

/* 2026-10-24 · Density and calm home. This is the last visual stylesheet loaded.
   Preserve 44px tap areas; distinguish communes by very subtle, non-semantic tints.
   Avoid another pile of competing phone-specific styles elsewhere. */
@media(max-width:800px){
  /* Native-app density: one search, one category rail, no redundant hero. */
  /* Lightweight primary shortcuts remain visible on the first screen. */
  /* Catalogue counts are already in the heading. The utility menu retains the full activity centre. */
  /* Light navigation like the user's reference; active icons use brand green. */
  .neoShell .neoNotice{bottom:calc(63px + env(safe-area-inset-bottom))}
  .neoShell a{scroll-margin-bottom:calc(68px + env(safe-area-inset-bottom))}
  /* Do not overcrowd or clip filter options on smaller phones. */
}

/* Consistent device rendering: prevent browser's arbitrary text inflation
   on two mobile contexts while preserving OS/browser accessibility zoom. */
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
@media(max-width:800px){
  /* Own publications have two management controls that must not enlarge the card's text. */
  .neoShell .neoOwnActions{gap:6px;margin-top:6px}
  .neoShell .neoOwnActions button{min-height:44px;font-size:10.5px;line-height:1.15;padding:6px 8px}
  .tcActivityCenter .tcActivityPush{white-space:normal;line-height:1.22}
}

/* Mobile footer and territorial support sections, unified visual owner.
   Keep these separate from the job feed; all links and accordions stay functional. */
@media(max-width:800px){
  .neoShell .tcTerritorialRadar,.neoShell .tcSecondary{
    box-sizing:border-box;width:calc(100% - 28px);
    margin:2px auto;padding:0 6px;
    border:0;border-bottom:1px solid #e8eee7;border-radius:0;
    background:transparent;box-shadow:none;
  }
  .neoShell .tcTerritorialRadar{padding:7px 6px 0}
  .neoShell .tcRadarHeading{gap:6px;min-height:24px}
  .neoShell .tcRadarHeading h2{font-size:14.5px;line-height:1.2;font-weight:650;margin:0}
  .neoShell .tcRadarHeading p{display:none}
  .neoShell .tcRadarHeading>svg{width:17px;height:17px;flex-shrink:0}
  .neoShell .tcRadarDetails>summary{
    min-height:44px;font-size:11.5px;line-height:1.2;
    padding:0 1px;color:#526f5b
  }
  .neoShell .tcRadarDetails>summary span{font-size:16px}
  .neoShell .tcSecondary>summary{
    display:flex;align-items:center;justify-content:space-between;
    min-height:46px;padding:3px 1px;gap:12px;
    font-size:13.5px;font-weight:640;line-height:1.2;
    color:#203e2d;letter-spacing:-.005em;
  }
  .neoShell .tcSecondary>summary::after{
    content:'+';display:grid;place-items:center;
    flex:0 0 28px;width:28px;height:28px;border-radius:50%;
    font-size:19px;background:transparent;color:#426a4b
  }
  .neoShell .tcSecondary[open]>summary::after{content:'−'}
  .neoShell .tcSecondary[open]{padding-bottom:9px}
  /* Footer is four distinct lines instead of logo + legal text collision. */
}

/**
 * Public-facing copy only. The original source, URL, provenance and engine
 * evidence remain intact in backend records and the admin diagnostics.
 */
export function publicSourceLabel(source?:string|null):string {
  const text=(source||'').trim().replace(/\s+/g,' ');
  if(!text)return 'Fuente externa';
  // No URL, hostname, tracking suffix, technical provider label on cards.
  if(/https?:\/\/|(?:^|\s)www\.|[a-z0-9-]+\.(?:cl|com|org|net)(?:\/|\b)/i.test(text))return 'Fuente externa';
  if(/^(?:fuente externa|fuente p[úu]blica|portal de empleos?|portal laboral|fuente no informada|fuente desconocida)\b/i.test(text))
    return 'Fuente externa';
  // Official named publishers can help applicants identify who published it.
  const named=/^(?:(?:municipalidad|ilustre municipalidad)(?: de)?\s+[\p{L}0-9 .,'-]+|OMIL\s+[\p{L}0-9 .,'-]+|Hospital\s+[\p{L}0-9 .,'-]+|Servicio de Salud\s+[\p{L}0-9 .,'-]+|CONAF|Empleos P[úu]blicos|Bolsa Nacional de Empleo)$/iu;
  if(text.length<=53&&named.test(text)&&!/motor|pipeline|ocr|crawler|adapter/i.test(text))return text;
  return 'Fuente externa';
}
/** Don't present scanning, verification and batch-routing notes as job duties. */
export function publicOfferDetail(note?:string|null):string|null {
  const text=(note||'').trim().replace(/\s+/g,' ');
  if(!text||/^(?:sin descripci[oó]n adicional|n\/a|no informad[ao])\.?$/i.test(text))return null;
  if(/^(?:(?:motor\s*(?:[ABCD]|chat\s*gpt|gemini)|rastreador|radar interno|evidencia de fuente|origen chat\s*gpt|verificaci[oó]n t[ée]cnica|lector documental)\s*[:：—-])/i.test(text))return null;
  if(/\b(?:deduplicaci[oó]n|pipeline|catalog[oa] p[úu]blico|proyecci[oó]n p[úu]blica|batch(?:_id)?|revisi[oó]n express|fecha original, empresa, lugar de trabajo|publicaci[oó]n de hoy o ayer|ficha individual, fecha original)\b/i.test(text))return null;
  return text;
}

/* Trabajo Cerca · Public experience, phase 1.
   This layer changes only presentation. No form fields, handlers, SDK or admin rules. */
.tcStitchShell .modal:not(.neoAlertsModal){
  background:rgba(9,33,24,.62);
  backdrop-filter:blur(7px);
  padding:16px;
  z-index:120;
}
.tcStitchShell .modal:not(.neoAlertsModal) .panel,
.tcStitchShell .modal:not(.neoAlertsModal) .detailSheet{
  --forest:#174934;--forest-deep:#103529;--terracotta:#267447;
  --line:#d7dfd4;--ivory:#f7f9f6;
  background:#fff;color:#103529;border:1px solid #d7dfd4;
  border-radius:20px;box-shadow:0 24px 70px rgba(9,33,24,.24);
  max-height:min(92dvh,960px);overscroll-behavior:contain;
  font-family:Inter,Arial,sans-serif;
}
.tcStitchShell .modal:not(.neoAlertsModal) .panel{width:min(620px,100%);padding:clamp(18px,3vw,32px)}
.tcStitchShell .modal:not(.neoAlertsModal) .panel h2,
.tcStitchShell .modal:not(.neoAlertsModal) .detailHeader h2{
  font-family:'Plus Jakarta Sans',Inter,sans-serif;
  color:#103529;font-size:clamp(22px,2.5vw,30px);line-height:1.2;letter-spacing:-.035em;
}
.tcStitchShell .modal:not(.neoAlertsModal) .panel>p,
.tcStitchShell .modal:not(.neoAlertsModal) .panel label,
.tcStitchShell .modal:not(.neoAlertsModal) .smartForm legend{
  font-size:13px;line-height:1.5;color:#4a584e;
}
.tcStitchShell .modal:not(.neoAlertsModal) .lab{font-size:11px;color:#267447;letter-spacing:.05em}
.tcStitchShell .modal:not(.neoAlertsModal) .panel form{gap:16px}
.tcStitchShell .modal:not(.neoAlertsModal) .panel input:not([type=checkbox]):not([type=radio]):not([type=file]),
.tcStitchShell .modal:not(.neoAlertsModal) .panel select,
.tcStitchShell .modal:not(.neoAlertsModal) .panel textarea{
  min-height:44px;padding:11px 13px;border:1px solid #cbd8cd;border-radius:11px;
  background:#fff;color:#103529;font-size:14px;line-height:1.45;
}
.tcStitchShell .modal:not(.neoAlertsModal) .panel textarea{min-height:100px}
.tcStitchShell .modal:not(.neoAlertsModal) .panel :is(input,textarea,select,button,a):focus-visible,
.tcStitchShell .modal:not(.neoAlertsModal) .detailSheet :is(button,a):focus-visible{
